INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('b1156d84-347e-4457-b606-e3cdb3b0c3d9', 'ec4f69b9-567a-437e-8b7e-3cc74fc2de48', '41267a46-87ff-49a3-a197-661f50b2aadc', 35, NULL, FALSE, 'text = ''the quick brown fox the lazy dog the''
words = text.split()

# Count occurrences of each word
word_counts = {}
for word in words:
    word_counts[word] = word_counts.get(word, 0) + 1

# Find the word with the maximum count
most_frequent = max(word_counts, key=word_counts.get)

print(most_frequent)
');
