INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('797a396b-7a8a-4658-9c04-0699e9f5f318', 'ec4f69b9-567a-437e-8b7e-3cc74fc2de48', 'da0e6aba-f03c-42f6-a7a9-71b0df517c78', 7, NULL, FALSE, 'def fibonacci(n):
    # Base cases for 0 and 1
    if n <= 1:
        return n
    # Recursive call for the sum of the two previous numbers
    return fibonacci(n - 1) + fibonacci(n - 2)

print(fibonacci(10))');
INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('e1228bec-9dda-4de2-b5f3-d9f8c78e9ee9', 'ec4f69b9-567a-437e-8b7e-3cc74fc2de48', '0028dbfb-333e-4894-a38b-33f49d67279e', 11, NULL, FALSE, 'import re
s = ''contact: a@test.com or b@example.org''

# Define regex pattern for email addresses
# [\w\.-]+ matches the username, @ matches the symbol, 
# [\w\.-]+ matches the domain, \.\w+ matches the extension
pattern = r''[\w\.-]+@[\w\.-]+\.\w+''

# Extract all matches into a list
emails = re.findall(pattern, s)

# Print the result
print(emails)');
INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('393867c5-e007-4ee0-9bcc-f61583fa1c78', 'ec4f69b9-567a-437e-8b7e-3cc74fc2de48', '9d86e643-9555-4d5e-89ef-92387d87769b', 3, NULL, FALSE, 'def is_prime(n, i=2):
    # Base cases for non-prime and prime
    if n < 2: return False
    if i * i > n: return True
    if n % i == 0: return False
    
    # Recursive call with next divisor
    return is_prime(n, i + 1)

# Print the result for 17
print(is_prime(17))');
INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('e658713f-6846-4cde-b7b3-8f4068f31330', 'ec4f69b9-567a-437e-8b7e-3cc74fc2de48', '2bc5dec0-d580-41f6-a1b9-047c8334c915', 32, NULL, FALSE, '
class Rectangle:
    def __init__(self, width, height):
        # Assign width and height to the instance
        self.width = width
        self.height = height
        
    def area(self):
        # Return the calculated area
        return self.width * self.height

r = Rectangle(4, 5)
print(r.area())');
INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('8912a160-5e0c-4cac-a449-cd912f0e5460', 'ec4f69b9-567a-437e-8b7e-3cc74fc2de48', 'a368dba9-fd82-4c95-85ab-388f88b02d03', 44, NULL, FALSE, 'nums = [5, 3, 8, 1, 9]

# Bubble sort implementation
n = len(nums)
for i in range(n):
    # Last i elements are already in place
    for j in range(0, n - i - 1):
        # Swap if the element found is greater than the next element
        if nums[j] > nums[j + 1]:
            nums[j], nums[j + 1] = nums[j + 1], nums[j]

print(nums)
');
INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('1a92b740-1d0a-49f0-8108-ed4da23739e1', 'ec4f69b9-567a-437e-8b7e-3cc74fc2de48', '18aff3fc-1865-4a20-b5ed-6a2c9a1ac549', 18, NULL, FALSE, 'import sqlite3
