INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('edee16c3-b50c-45ef-bd0d-2ddbf30c5995', '85cb6985-77ce-48c1-b316-2395a3eb0fb6', '19969c69-cb24-4215-95e5-17cff92bcbac', 18, NULL, TRUE, 'def make_counter():
    count = 0  # Initialize the counter variable

    def counter():
        nonlocal count  # Declare count as nonlocal so we can modify it
        count += 1      # Increment the counter
        return count    # Return the current count

    return counter  # Return the closure

c = make_counter()
c()
c()
print(c())  # This will print 3');
INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('b42cbc1f-9c9e-4b7d-af5a-26aa058771b7', '85cb6985-77ce-48c1-b316-2395a3eb0fb6', 'd7b7fb62-c26d-466b-9444-cb6ce0097572', 42, NULL, TRUE, 'a = {''x'': 1, ''y'': 2}
