INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('ebec929c-ce40-4dac-8cae-20578f57295c', '85cb6985-77ce-48c1-b316-2395a3eb0fb6', '18aff3fc-1865-4a20-b5ed-6a2c9a1ac549', 13, NULL, TRUE, 'import sqlite3
