INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('700d295f-6eca-401e-b554-a90bf23e7c09', 'b3b92627-a187-4996-b532-3a0ca580ece9', '396b6e14-0f54-4288-9be5-01464305d532', 28, NULL, FALSE, 'import sqlite3
