INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('b90333be-278e-4f59-a29d-cf7d82f7c57f', '6ae2e550-1673-4e41-a437-2ff6227f0e95', '37f69031-edeb-461d-90b3-035b9f8ded7b', 33, NULL, TRUE, 'import sqlite3
