INSERT INTO "AttemptQuestion" ("id", "attemptId", "questionId", "order", "selectedOption", "isCorrect", "submittedCode") VALUES ('a304dbf3-17f5-47a2-bb8f-065dd2d53754', '6ae2e550-1673-4e41-a437-2ff6227f0e95', '74f607f5-b233-45c9-83ac-2a54bfe31821', 24, NULL, TRUE, 'class Shape:
    def area(self):
        return 0

class Square(Shape):
    def __init__(self, side):
        self.side = side
    # your code here
    def area(self):
        return self.side * self.side
s = Square(4)
print(s.area())');

