INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('0b92b808-b8cc-45e1-b807-3d32e52c8ee7', 'What does this print?

score = -0.6
if score >= 0.05:
    label = ''positive''
elif score <= -0.05:
    label = ''negative''
else:
    label = ''neutral''
print(label)', '["Error","neutral","positive","negative"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-02T21:08:36.532Z', NULL, 'OUTPUT_BASED', NULL, 'Sentiment Analysis & Text Classification', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('e720905a-12ee-4a16-b2ff-170ff754311d', 'What does this print?

positive_words = [''great'',''excellent'']
text = ''the service was excellent''
count = sum(1 for w in positive_words if w in text)
print(count > 0)', '["Error","True","False","1"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-02T21:08:36.532Z', NULL, 'OUTPUT_BASED', NULL, 'Sentiment Analysis & Text Classification', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('168140c2-0c92-485e-80f4-89c5382a6e18', 'What does this print?

import string
text = ''Hi!!! How are you?''
cleaned = ''''.join(ch for ch in text if ch not in string.punctuation)
print(cleaned)', '["Hi!!! How are you?","Hi How are you","Hi How are you ","HiHowareyou"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-02T20:35:20.551Z', NULL, 'OUTPUT_BASED', NULL, 'Text Preprocessing', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('37820b39-3511-4c4e-b05d-3b29fc14e368', 'What does this print?

negative_words = [''bad'',''terrible'',''awful'']
text = ''the food was awful and cold''
found = [w for w in negative_words if w in text]
print(found)', '["[]","[''cold'']","[''bad'', ''terrible'', ''awful'']","[''awful'']"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-02T21:08:36.532Z', NULL, 'OUTPUT_BASED', NULL, 'Sentiment Analysis & Text Classification', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('9cc0a9d6-a172-4a24-a7be-cd3d74b4582d', 'Which process converts text into individual words or subword units?', '["Stemming","Vectorisation","Tokenisation","Lemmatisation"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-02T20:35:20.551Z', NULL, 'MCQ', NULL, 'Text Preprocessing', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('37b91961-5b07-475c-9322-dd4dd2f0b7cd', 'What is the main difference between stemming and lemmatisation?', '["Stemming is more accurate than lemmatisation","Stemming requires a language model; lemmatisation does not","Lemmatisation produces valid dictionary words using vocabulary and grammar rules; stemming crudely chops word endings","They are the same process with different names"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-02T20:35:20.551Z', NULL, 'MCQ', NULL, 'Text Preprocessing', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('f1c8f503-7c57-4d83-827a-870bc7105791', 'What does this print?

import spacy
nlp = spacy.load(''en_core_web_sm'')
doc = nlp(''Apple is looking at buying a startup in London.'')
for ent in doc.ents:
    print(ent.text, ent.label_)', '["No entities found","Apple PERSON\nLondon LOC","Apple ORG\nLondon GPE","Apple ORG\nstartup PRODUCT\nLondon GPE"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-02T20:35:20.551Z', NULL, 'OUTPUT_BASED', NULL, 'POS Tagging & NER', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('fd51bf6a-03d0-45a4-81a5-b0e33e23de56', 'VADER''s sentiment output includes a ''compound'' score. What range does this compound score typically fall within?', '["0 to 100","1 to 5 star rating","-1 (most negative) to +1 (most positive)","-infinity to +infinity"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-02T20:35:20.551Z', NULL, 'MCQ', NULL, 'Sentiment Analysis & Text Classification', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('11d0f70d-7dfe-4fd1-b83b-d0240f2a83b7', 'What is the primary purpose of lowercasing text during preprocessing?', '["To translate the text","To reduce the number of sentences","To make the text print faster","To ensure words like ''The'' and ''the'' are treated as the same token"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-02T21:08:36.532Z', NULL, 'MCQ', NULL, 'Text Preprocessing', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('72c69c5a-325a-40a1-bcb0-4f0c1a8d3c32', 'Which preprocessing decision is MOST likely to hurt performance on a sentiment analysis task specifically?', '["Lowercasing all text","Removing stop words like ''not'' and ''no'' before sentiment scoring","Removing extra whitespace","Removing HTML tags"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Text Preprocessing', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('e8ae5cf0-3d32-4bba-946f-b03223783542', 'What is a key risk of aggressive stemming (e.g., reducing ''university'' and ''universe'' both toward ''univers'')?', '["It makes text processing slower","It requires internet access","It only works on numbers","Overstemming, where unrelated words collapse to the same root, losing meaning distinctions"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Text Preprocessing', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('16cabad6-9020-4f0f-84d5-9dc544f4a792', 'In subword tokenization (e.g., Byte-Pair Encoding used by many LLMs), why might a rare word like ''anticonstitutionally'' get split into multiple tokens?', '["To make the sentence grammatically correct","Because BPE only works on numbers","To represent rare/unseen words using combinations of known frequent subword units, avoiding a fixed vocabulary limit","Because the word is too long to fit in memory"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Text Preprocessing', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('7d2df553-18d2-48bb-b6d2-ebb232b5bf91', 'Why can rule-based/dictionary-only NER systems struggle with the word ''Amazon'' across different sentences?', '["Because NER cannot process 6-letter words","Because ''Amazon'' is not a real word","Because ''Amazon'' is always a PERSON","Because ''Amazon'' can refer to different entity types (ORG for the company, LOC for the river/rainforest) depending on context, which rules alone can''t disambiguate"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'POS Tagging & NER', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('c6a07eba-bda3-4f44-8fe8-c5006ac25208', 'What does it mean for a POS tagger to use context window information rather than tagging each word in isolation?', '["It only looks at the first word of the sentence","It ignores punctuation entirely","It requires the whole document to be one word","It considers surrounding words to resolve ambiguity (e.g., ''book'' as noun vs verb depends on context)"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'POS Tagging & NER', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('7db45c37-e81e-4121-9e5f-853275cc1c0e', 'What is a known limitation of statistical NER models trained primarily on news-domain text, when applied to social media text?', '["They automatically translate to other languages","Performance often drops due to informal language, slang, and unconventional capitalization not seen in training data","They stop recognizing PERSON entities entirely","They become faster"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'POS Tagging & NER', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('11e473cb-63e2-49f8-aa1d-1605b4c94c77', 'Why might raw term frequency alone, without an IDF-style component, be a poor keyword extraction method for SEO?', '["Raw term frequency is always more accurate than TF-IDF","It would rank extremely common words as top keywords since it ignores how distinctive a word is across documents","Term frequency requires labeled training data","Term frequency cannot be computed for English text"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Keyword Extraction — TF-IDF & YAKE', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('cc7bc2fc-8fb0-47fa-8764-a76802341277', 'YAKE uses a ''lower score is better'' convention. If Word A scores 0.02 and Word B scores 0.15, which is the more relevant keyword?', '["Cannot be determined","Word A","They are equally relevant","Word B"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Keyword Extraction — TF-IDF & YAKE', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('b0733214-edfa-4bbb-9207-07f743ef6887', 'Two documents share the exact same top TF-IDF keyword. What can you reasonably conclude?', '["TF-IDF cannot produce this result","One document must be plagiarized from the other","The documents likely share a similar core topic, but could still differ substantially in supporting details or intent","The documents are word-for-word identical"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Keyword Extraction — TF-IDF & YAKE', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('36fbfb45-1903-4c86-bdde-6d09720e4f80', 'Why can two sentences with almost no overlapping words still have high cosine similarity in embedding space?', '["Embeddings only work on identical sentences","Cosine similarity ignores word order only","Embeddings capture semantic meaning, not just literal word overlap, so synonyms and paraphrases are captured","Embeddings are random and similarity is coincidental"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Text Embeddings & Semantic Similarity', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('490518f3-33d9-4dd3-8691-9fedf89b4a0f', 'What is a practical reason to reduce embedding dimensionality (e.g., from 768 to 128) before storing millions of documents in a vector database?', '["It increases the number of documents you''re allowed to store for free","It removes the need for a vector database entirely","To reduce storage cost and speed up similarity search, at some potential cost to accuracy","Higher dimensions are illegal to store"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Text Embeddings & Semantic Similarity', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('99b7d3bd-6d7a-46ff-8dfc-53dbe3ac627a', 'Content A has high cosine similarity to your target keyword''s embedding, but does NOT rank well in search results. What does this suggest?', '["The embedding model is broken","Semantic relevance alone doesn''t guarantee ranking; other SEO factors like backlinks and technical SEO also matter","Cosine similarity is never useful for SEO","The content must be removed immediately"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Text Embeddings & Semantic Similarity', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('b8fb931a-cc09-4f01-a4f8-8cb260a4fece', 'Why do rule-based sentiment tools like VADER often struggle with sarcasm (e.g., ''Oh great, another Monday...'')?', '["They automatically detect all sarcasm correctly","They only work on questions","They require a working internet connection","They score words heuristically and generally can''t detect the contextual irony that flips literal positive words into negative sentiment"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Sentiment Analysis & Text Classification', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('11d56f8d-2959-43f4-b515-1729deac9178', 'A binary sentiment classifier (positive/negative only) is applied to a neutral review like ''The product arrived on time.'' What is the most likely practical problem?', '["This is not a real limitation","The model is forced to pick positive or negative even though neither fits, introducing noise into aggregate sentiment reports","The model will crash","The review will be automatically deleted"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Sentiment Analysis & Text Classification', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('2aa1e353-f470-4c2e-b106-92f81dea599a', 'Why might a sentiment model trained mostly on product reviews perform poorly when applied to classifying news headlines?', '["There is no difference between domains for sentiment models","News headlines are always neutral so no model is needed","Domain shift — vocabulary, tone, and what counts as positive/negative differ significantly between domains","Product review models are illegal to use elsewhere"]'::jsonb, 2, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Sentiment Analysis & Text Classification', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('3250341b-4dcd-4f98-b14e-15cb4df59323', 'Why does increasing an LLM''s context window (e.g., from 8K to 128K tokens) NOT automatically mean the model perfectly uses all that information?', '["Context window size has no effect on model behavior","Context window only affects response speed, never quality","Larger context windows always improve accuracy uniformly","Models can exhibit a ''lost in the middle'' effect, attending less reliably to information in the middle of very long contexts"]'::jsonb, 3, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Introduction to LLMs', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('40344bee-b707-4027-bfb0-59a611f9eaa0', 'In few-shot prompting, why might providing too many examples sometimes hurt performance rather than help?', '["Few-shot prompting stops working after exactly 2 examples","It can consume excessive context budget and may bias the model toward rigid pattern-matching rather than generalizing","Examples are ignored by the model entirely","More examples always strictly improve performance with no downside"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Introduction to LLMs', 0, FALSE);
INSERT INTO "Question" ("id", "text", "options", "correctOption", "type", "difficulty", "createdAt", "expectedOutput", "questionType", "starterCode", "topic", "partOrder", "retired") VALUES ('d2820073-3880-4a32-9039-4df1bcdd98a6', 'A team evaluates two summarization models using only ROUGE scores and picks the higher-scoring one for production. What is a key risk of this approach?', '["There is no risk; ROUGE is a perfect quality metric","ROUGE measures n-gram overlap with reference summaries and may not fully capture fluency, factual accuracy, or true quality","ROUGE scores are always 100% correlated with human judgment","ROUGE cannot be computed for English text"]'::jsonb, 1, 'NLP_MAJOR', 'hard', '2026-09-13T06:28:41.689Z', NULL, 'MCQ', NULL, 'Introduction to LLMs', 0, FALSE);

